text:
{
  "items": [
    {
      "index": 1,
      "scene": "文具图书购买",
      "angle": "已知单支钢笔单价，求购买整数支数的总费用，列竖式计算。"
    },
    {
      "index": 2,
      "scene": "动物身体数据",
      "angle": "根据蜂鸟体重与倍数关系，判断积的小数位数并填空，无需算出结果。"
    },
    {
      "index": 3,
      "scene": "农场养殖与种植",
      "angle": "已知果园苹果总产量，求其中红富士品种（占几分之几）的具体重量。"
    },
    {
      "index": 4,
      "scene": "资源与环保统计",
      "angle": "已知每回收1吨废纸节约的水量，求回收整数吨废纸共节约多少吨水。"
    },
    {
      "index": 5,
      "scene": "家居装修与铺地",
      "angle": "给出两个因数，要求直接写出它们乘积的小数位数，考察位值原理。"
    },
    {
      "index": 6,
      "scene": "自驾与导航",
      "angle": "已知汽车油箱总容量，求行驶一段路程后消耗的油量（占总量的几分之几）。"
    },
    {
      "index": 7,
      "scene": "手工制作与折纸",
      "angle": "已知制作一个中国结所需绳长，求制作整数个中国结所需的绳子总长度。"
    },
    {
      "index": 8,
      "scene": "体育比赛计分",
      "angle": "根据跳水动作难度系数与完成分（小数），推断最终得分积的小数位数。"
    },
    {
      "index": 9,
      "scene": "铁路高铁行程",
      "angle": "已知两地铁路全长，求列车行驶完全程的几分之几时所在的具体里程位置。"
    },
    {
      "index": 10,
      "scene": "公共交通出行",
      "angle": "已知地铁每千米造价，求修建整数千米线路所需的总资金，列式计算。"
    }
  ]
}
